 * This demonstrates how to use the retry function with exponential backoff
 */

const { retry } = require('acme-retry');

/**
 * A flaky function that simulates a network request or API call
 * that fails sometimes but succeeds on later attempts
 */
async function flakyFunction(attemptNumber) {
  console.log(`Attempt ${attemptNumber}: Calling flaky function...`);

  // Simulate different failure scenarios
  if (attemptNumber <= 2) {
    // Fail on first 2 attempts
    throw new Error(`Simulated failure on attempt ${attemptNumber}`);
  }

  // Succeed on 3rd attempt
  return `Success on attempt ${attemptNumber}!`;
}

/**
 * Wrapper to track attempt numbers
 */
function createFlakyFunctionWrapper() {
  let attempt = 1;
  return async () => {
    const result = await flakyFunction(attempt);
    attempt++;
    return result;
  };
}

/**
 * Main example demonstrating 5 retry attempts
 */
async function main() {
  console.log('=== acme-retry Example ===');
  console.log('Demonstrating retry with exponential backoff (5 attempts)\n');

  try {
    const result = await retry(createFlakyFunctionWrapper(), {
      attempts: 5,
      baseMs: 100  // Starting delay of 100ms
    });

    console.log(`\n✅ Final result: ${result}`);
  } catch (error) {
    console.log(`\n❌ All attempts failed: ${error.message}`);
  }

  console.log('\n=== How it works ===');
  console.log('The retry function:');
  console.log('1. Takes an async function and options object');
  console.log('2. Defaults to 3 attempts if not specified');
  console.log('3. Uses exponential backoff: delay = baseMs * 2^attempt');
  console.log('   - Attempt 1: immediate');
  console.log('   - Attempt 2: 100ms delay');
  console.log('   - Attempt 3: 200ms delay');
  console.log('   - Attempt 4: 400ms delay');
  console.log('   - Attempt 5: 800ms delay');
  console.log('4. Returns the first successful result');
  console.log('5. Throws the last error if all attempts fail');
}

// Another example: retrying an HTTP request simulation
async function simulateNetworkRequest() {
  console.log('\n=== Additional Example: Network Request ===');

  let requestCount = 0;

  const networkRequest = async () => {
    requestCount++;
    console.log(`Network request attempt ${requestCount}`);

    // Simulate 30% success rate
    if (Math.random() > 0.3) {
      throw new Error(`Network timeout on attempt ${requestCount}`);
    }

    return `Network request succeeded on attempt ${requestCount}`;
  };

  try {
    const result = await retry(networkRequest, { attempts: 5, baseMs: 50 });
    console.log(`✅ ${result}`);
  } catch (error) {
    console.log(`❌ Network request failed after all retries: ${error.message}`);
  }
}

// Run the examples
(async () => {
  await main();
  await simulateNetworkRequest();
})();

