// Example usage of acme-retry package
const { retry } = require('acme-retry');

// A simple flaky function that randomly fails
async function flakyFunction(attemptNumber) {
  console.log(`Attempt #${attemptNumber}: Calling flaky function...`);

  // Simulate a random failure (50% chance)
  if (Math.random() < 0.5) {
    throw new Error(`Random failure on attempt ${attemptNumber}`);
  }

  // If we get here, the operation succeeded
  return `Success on attempt ${attemptNumber}`;
}

// Counter to track which attempt we're on
let attemptCounter = 0;

// Create a wrapper function that increments our counter
async function flakyFunctionWithCounter() {
  attemptCounter++;
  return await flakyFunction(attemptCounter);
}

// Main example
async function main() {
  console.log('=== acme-retry Example ===');
  console.log('This example demonstrates retrying a flaky function 5 times with exponential backoff.\n');

  // Reset the counter
  attemptCounter = 0;

  try {
    // Use acme-retry to call our flaky function
    const result = await retry(flakyFunctionWithCounter, {
      attempts: 5,        // Try up to 5 times
      baseMs: 200        // Start with 200ms delay, doubling each time
    });

    console.log(`\n✅ Final result: ${result}`);

  } catch (error) {
    console.log(`\n❌ All attempts failed: ${error.message}`);
  }

  console.log('\n\n=== How acme-retry works ===');
  console.log('1. The retry() function takes a function to execute and options:');
  console.log('   - attempts: Maximum number of retry attempts (default: 3)');
  console.log('   - baseMs: Base delay in milliseconds (default: 100)');
  console.log('\n2. It uses exponential backoff:');
  console.log('   - 1st retry: baseMs * 2^0 = 200ms delay');
  console.log('   - 2nd retry: baseMs * 2^1 = 400ms delay');
  console.log('   - 3rd retry: baseMs * 2^2 = 800ms delay');
  console.log('   - 4th retry: baseMs * 2^3 = 1600ms delay');
  console.log('   - And so on...');
  console.log('\n3. If any attempt succeeds, it returns the result immediately.');
  console.log('4. If all attempts fail, it throws the last error encountered.');
}

// Run the example
if (require.main === module) {
  main().catch(console.error);
}

module.exports = {
  flakyFunction,
  flakyFunctionWithCounter,
  main
};

