#!/usr/bin/env node

// Web API example using acme-retry
const { retry } = require('acme-retry');

// Simulate an external API call that might fail
async function callExternalAPI(apiName) {
  console.log(`Calling ${apiName} API...`);

  // Simulate various failure modes
  const random = Math.random();

  if (random < 0.3) {
    // 30% chance: Rate limit error
    throw new Error(`${apiName}: Rate limit exceeded (429)`);
  } else if (random < 0.5) {
    // 20% chance: Timeout error
    throw new Error(`${apiName}: Request timed out (504)`);
  } else if (random < 0.7) {
    // 20% chance: Server error
    throw new Error(`${apiName}: Internal server error (500)`);
  }

  // 30% chance: Success
  return {
    success: true,
    api: apiName,
    data: { message: `Data from ${apiName}`, timestamp: new Date().toISOString() }
  };
}

// Enhanced retry with logging
async function retryWithLogging(fn, opts = {}) {
  const startTime = Date.now();
  const maxAttempts = opts.attempts ?? 3;

  console.log(`\n📡 Starting operation with ${maxAttempts} max attempts...`);

  try {
    const result = await retry(fn, opts);
    const elapsed = Date.now() - startTime;
    console.log(`✅ Operation succeeded in ${elapsed}ms`);
    return result;
  } catch (error) {
    const elapsed = Date.now() - startTime;
    console.log(`❌ Operation failed after ${maxAttempts} attempts (${elapsed}ms)`);
    console.log(`   Last error: ${error.message}`);
    throw error;
  }
}

// Example: Retrying different types of operations
async function runWebExamples() {
  console.log('=== Web API Retry Examples ===\n');

  // Example 1: Payment processing with retry
  console.log('1. Payment processing (critical operation):');
  try {
    const paymentResult = await retryWithLogging(
      () => callExternalAPI('payment-gateway'),
