const { retry } = require('acme-retry');

/**
 * Example of a flaky function that sometimes fails
 * This function simulates a flaky API call or network operation
 * that fails with probability 0.7 (70% of the time)
 */
function flakyFunction() {
  return new Promise((resolve, reject) => {
    // Simulate some work
    const workTime = Math.random() * 200;

    setTimeout(() => {
      const random = Math.random();

      // Fail 70% of the time to demonstrate retry behavior
      if (random < 0.7) {
        console.log(`  ❌ Function failed (random=${random.toFixed(2)})`);
        reject(new Error(`Flaky function failed with random value ${random.toFixed(2)}`));
      } else {
        console.log(`  ✅ Function succeeded (random=${random.toFixed(2)})`);
        resolve(`Success! Work took ${workTime.toFixed(0)}ms`);
      }
    }, workTime);
  });
}

/**
 * Example usage of acme-retry
 */
async function runExample() {
  console.log('=== ACME-RETRY EXAMPLE ===');
  console.log('This example demonstrates retrying a flaky function 5 times with exponential backoff');
  console.log('The flaky function fails ~70% of the time\n');

  try {
    console.log('Attempting to execute flaky function with retry logic...');

    // Use acme-retry to retry the flaky function 5 times
    // with base delay of 100ms (exponential backoff: 100, 200, 400, 800, 1600ms)
    const result = await retry(flakyFunction, {
      attempts: 5,
      baseMs: 100
    });

    console.log(`\n🎉 Final result: ${result}`);

  } catch (error) {
    console.log(`\n💥 All attempts failed: ${error.message}`);
  }

  console.log('\n=== HOW IT WORKS ===');
  console.log('1. The retry() function takes a function fn and options object');
  console.log('2. It attempts to execute fn() up to opts.attempts times (default: 3)');
  console.log('3. Exponential backoff: waits baseMs * 2^i between attempts');
  console.log('   where i is the attempt number (0-based)');
  console.log('4. If fn() succeeds, returns its result immediately');
  console.log('5. If all attempts fail, throws the last error');
  console.log('6. Simple but effective for handling transient failures');
}

// Run the example
runExample().catch(console.error);

const { retry } = require('acme-retry');

/**
 * ADVANCED EXAMPLE: Different retry strategies and use cases
 */

// Example 1: Simulating API call with increasing delay
async function simulateAPICall() {
  console.log('\n=== EXAMPLE 1: API Call Simulation ===');

  let callCount = 0;
  const apiCall = async () => {
    callCount++;
    console.log(`  API Call attempt #${callCount}`);

    // Simulate network issues that get resolved after a few attempts
    if (callCount < 3) {
      throw new Error(`HTTP 503 - Service Unavailable (attempt ${callCount})`);
    }

    return { data: `API response from attempt ${callCount}`, status: 'success' };
  };

  try {
    const result = await retry(apiCall, { attempts: 5, baseMs: 200 });
    console.log(`  Result:`, result);
  } catch (error) {
    console.log(`  Failed: ${error.message}`);
  }
}

// Example 2: Database connection with custom backoff
async function simulateDatabaseConnection() {
  console.log('\n=== EXAMPLE 2: Database Connection ===');

  const connectToDB = async () => {
    console.log(`  Attempting database connection...`);

    // Simulate connection that works 40% of the time
    if (Math.random() < 0.6) {
      throw new Error('Connection timeout - database not responding');
    }

    return { connected: true, message: 'Database connection established' };
  };

  try {
    // Use longer base delay for database operations
    const result = await retry(connectToDB, { attempts: 4, baseMs: 300 });
    console.log(`  ${result.message}`);
  } catch (error) {
    console.log(`  Database connection failed: ${error.message}`);
  }
}

// Example 3: File operation with default settings
async function simulateFileOperation() {
  console.log('\n=== EXAMPLE 3: File Operation (default settings) ===');

  let attempt = 0;
  const readFile = async () => {
    attempt++;
    console.log(`  File read attempt #${attempt}`);

    // File might be locked by another process initially
    if (attempt < 2 && Math.random() < 0.8) {
      throw new Error('File is locked or inaccessible');
    }

    return `File content from attempt ${attempt}`;
  };

  try {
    // Using default settings (3 attempts, 100ms base delay)
    const content = await retry(readFile);
    console.log(`  Successfully read: ${content}`);
  } catch (error) {
    console.log(`  File operation failed: ${error.message}`);
  }
}

// Example 4: Understanding the exponential backoff timing
async function demonstrateBackoffTiming() {
  console.log('\n=== EXAMPLE 4: Exponential Backoff Timing ===');

  const timedOperation = async (attemptNum) => {
    const startTime = Date.now();
    console.log(`  Attempt ${attemptNum + 1}: Starting at ${startTime}`);

    // Always fail to demonstrate all retries
    throw new Error(`Intentional failure on attempt ${attemptNum + 1}`);
  };

  console.log('Demonstrating retry with baseMs=100, attempts=5:');
  console.log('Expected wait times: 100ms, 200ms, 400ms, 800ms, 1600ms');

  // Create a wrapper that tracks attempt number
  let attemptCounter = 0;
  const operationWithCounter = async () => {
    return timedOperation(attemptCounter++);
  };

  try {
    await retry(operationWithCounter, { attempts: 5, baseMs: 100 });
  } catch (error) {
    console.log(`  Final error: ${error.message}`);
    console.log('  (All 5 attempts were made with exponential backoff)');
  }
}

// Example 5: Real-world usage pattern
async function realWorldExample() {
  console.log('\n=== EXAMPLE 5: Real-world Usage Pattern ===');

  // Simulate fetching user data from an external service
  const fetchUserData = async (userId) => {
    console.log(`  Fetching data for user ${userId}...`);

    // Simulate various temporary failures
    const random = Math.random();
    if (random < 0.3) {
      throw new Error('Network timeout');
    } else if (random < 0.6) {
      throw new Error('Service rate limited');
    } else if (random < 0.8) {
      throw new Error('Temporary server error');
    }

    return { userId, name: 'John Doe', email: 'john@example.com' };
  };

  // Common pattern: wrap retry logic in a helper function
  const fetchWithRetry = async (userId) => {
    return retry(() => fetchUserData(userId), {
      attempts: 4,
      baseMs: 150
    });
  };

  try {
    const userData = await fetchWithRetry('user-123');
    console.log(`  Success:`, userData);
  } catch (error) {
    console.log(`  Failed to fetch user data: ${error.message}`);
  }
}

// Main execution
async function runAllExamples() {
  console.log('=== ACME-RETRY ADVANCED EXAMPLES ===');
  console.log('Demonstrating various use cases and retry strategies\n');

  await simulateAPICall();
  await simulateDatabaseConnection();
  await simulateFileOperation();
  await demonstrateBackoffTiming();
  await realWorldExample();

  console.log('\n=== KEY TAKEAWAYS ===');
  console.log('1. Exponential backoff prevents overwhelming failing services');
  console.log('2. Useful for: API calls, database connections, file operations');
  console.log('3. Defaults are sensible (3 attempts, 100ms base)');
  console.log('4. Simple API: retry(fn, {attempts, baseMs})');
  console.log('5. Returns promise, works with async/await');
  console.log('6. Throws last error if all attempts fail');
}

runAllExamples().catch(console.error);

