const { retry } = require('acme-retry');

/**
 * Example demonstrating acme-retry package
 * This shows how to retry a flaky function 5 times with exponential backoff
 */

// A flaky function that simulates an unreliable API call
// It will fail the first 4 times, then succeed on the 5th attempt
let attemptCounter = 0;

const flakyApiCall = () => {
  attemptCounter++;
  console.log(`[Attempt ${attemptCounter}] Calling the flaky API...`);

  // Simulate failure for first 4 attempts
  if (attemptCounter < 5) {
    throw new Error(`API call failed (attempt ${attemptCounter})`);
  }

  console.log(`[Attempt ${attemptCounter}] Success!`);
  return { 
    status: 200, 
    message: 'Operation completed successfully',
    attemptNumber: attemptCounter
  };
};

async function main() {
  console.log('=== acme-retry Example ===\n');
  console.log('This example demonstrates retrying a flaky function 5 times');
  console.log('with exponential backoff (100ms base delay).\n');

  // Reset the counter
  attemptCounter = 0;

  try {
    // Use acme-retry to call our flaky function
    // It will retry up to 5 times with exponential backoff:
    // - Attempt 1: immediate
    // - Attempt 2: wait 100ms (100 * 2^0)
    // - Attempt 3: wait 200ms (100 * 2^1)
    // - Attempt 4: wait 400ms (100 * 2^2)
    // - Attempt 5: wait 800ms (100 * 2^3)
    const result = await retry(flakyApiCall, {
      attempts: 5,      // Retry up to 5 times
      baseMs: 100       // Base delay of 100ms
    });

    console.log('\n✅ Final result:', JSON.stringify(result, null, 2));
  } catch (error) {
    console.error('\n❌ All retries failed:', error.message);
  }
}

main().catch(console.error);
